import { useMemo, type ReactNode } from "react";
import {
  defaultShowToast,
  defaultUpdateToast,
  defaultDismissToast,
  defaultIsToastVisible,
} from "../Toaster";
import type {
  LogErrorFn,
  OnboardingTooltipConfig,
  ShowToastFn,
  UpdateToastFn,
  DismissToastFn,
  IsToastVisibleFn,
  TrackFn,
} from "../types";
import { InspectorContext } from "./InspectorContext";

interface Props {
  logError?: LogErrorFn;
  track?: TrackFn;
  showToast?: ShowToastFn;
  updateToast?: UpdateToastFn;
  dismissToast?: DismissToastFn;
  isToastVisible?: IsToastVisibleFn;
  onboardingTooltips?: OnboardingTooltipConfig[];
  socketReconnectAttempts?: number;
  children: ReactNode;
}

export const InspectorContextProvider = ({
  logError,
  track,
  showToast,
  updateToast,
  dismissToast,
  isToastVisible,
  onboardingTooltips,
  socketReconnectAttempts,
  children,
}: Props) => {
  const value = useMemo(
    () => ({
      logError: logError ?? console.error,
      track: track ?? (() => undefined),
      showToast: showToast ?? defaultShowToast,
      updateToast: updateToast ?? defaultUpdateToast,
      dismissToast: dismissToast ?? defaultDismissToast,
      isToastVisible: isToastVisible ?? defaultIsToastVisible,
      onboardingTooltips: onboardingTooltips ?? [],
      socketReconnectAttempts,
    }),
    [
      logError,
      track,
      showToast,
      updateToast,
      dismissToast,
      isToastVisible,
      onboardingTooltips,
      socketReconnectAttempts,
    ],
  );

  return <InspectorContext.Provider value={value}>{children}</InspectorContext.Provider>;
};
